head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > moveKeyEditModeAll]<br/>상/하/좌/우 방향키를 사용하여 Cell 이동과 함께 편집 모드로 변경할지 설정합니다.",
    "validation" : [
        "true 설정 시 상/하 방향키 입력 시 Cell 이동과 함께 편집 모드로 변경되며, 현재 Cell 이 편집 모드인 것과 관계없이 이동합니다.",
        "true 설정 시 좌/우 방향키 입력 시 현재 Cell 이 빈값이거나 Caret 이 첫번째 또는 마지막 문자에 있을때 인접 Cell 로 이동합니다.",
        "false(기본값) 설정 시 상/하 방향키 입력 시 현재 Cell 이 편집 모드인 경우 Cell 이동이 되지 않으며, 편집 모드가 아닌 경우 Cell 선택이 이동됩니다.",
        "false(기본값) 설정 시 좌/우 방향키 입력 시 현재 Cell 이 빈값이면 인접 Cell 로 이동하고, Cell 에 값이 입력된 경우 Caret 위치만 이동합니다.",        
        "Column 의 inputType 속성값에 관계없이 동작합니다.",
        "focusmove 속성값이 'false' 인 경우엔 moveKeyEditModeAll 속성이 동작하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // con_focusMove 기본값 true (focusMove 동작 전제조건 충족)
    con_focusMove.setValue("true");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 값 읽기
    let moveKeyEditModeVal = con_moveKeyEditMode.getValue();
    let moveKeyEditModeAllVal = con_moveKeyEditModeAll.getValue();
    let focusMoveVal = con_focusMove.getValue();

    // 동작 조건/현재 설정 라벨 생성
    $c.gcm.createLabel('label="컬럼 inputType 혼합: col1=text / col2=select / col3=secret / col4=calendar (편집형 inputType 다양화, inputType 무관 동작 확인용)"', '', 'label1');
    $c.gcm.createLabel('label="현재 설정: moveKeyEditModeAll=' + (moveKeyEditModeAllVal === '' ? '미설정(기본 false)' : moveKeyEditModeAllVal) + ' / moveKeyEditMode=' + (moveKeyEditModeVal === '' ? '미설정(기본 false)' : moveKeyEditModeVal) + ' / focusMove=' + (focusMoveVal === '' ? '미설정(기본 true)' : focusMoveVal) + '"', '', 'label2');

    // dataList 직접 생성 (4행)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    // col1(text) 값 채움(Caret 검증용, 단 row0 은 빈값=빈값 인접 이동 검증용) / col2(select)=Y,N 코드 / col3(secret)=숫자 / col4(calendar)=날짜
    // row0 col1='' (빈값 셀) 이지만 col2/col3/col4 에는 값이 있어 '행' 자체는 비지 않음(빈 행 카운트 0 유지)
    let textArr = ['', 'Banana', 'Cherry', 'Date'];
    let selArr = ['Y', 'N', 'Y', 'N'];
    let secretArr = ['1234', '5678', '9012', '3456'];
    let dateArr = ['20251101', '20251102', '20251103', '20251104'];
    for (let r = 0; r < 4; r++) {
        strDl += '<w2:row>';
        strDl += '<col1><![CDATA[' + textArr[r] + ']]></col1>';
        strDl += '<col2><![CDATA[' + selArr[r] + ']]></col2>';
        strDl += '<col3><![CDATA[' + secretArr[r] + ']]></col3>';
        strDl += '<col4><![CDATA[' + dateArr[r] + ']]></col4>';
        strDl += '</w2:row>';
    }
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);

    // moveKeyEditMode / moveKeyEditModeAll / focusMove 속성 (미설정 시 속성 미부여 = 기본값)
    let mkemAttr = moveKeyEditModeVal === '' ? '' : 'moveKeyEditMode="' + moveKeyEditModeVal + '" ';
    let mkemAllAttr = moveKeyEditModeAllVal === '' ? '' : 'moveKeyEditModeAll="' + moveKeyEditModeAllVal + '" ';
    let focusMoveAttr = focusMoveVal === '' ? '' : 'focusMove="' + focusMoveVal + '" ';

    // target 생성 (컬럼 inputType 혼합: text / select / secret / calendar)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + mkemAttr + mkemAllAttr + focusMoveAttr + 'editModeEvent="ondblclick" dataList="data:dlt_bind" checkAllType="false" id="" style="width:560px;height:250px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" inputType="text" id="column1" value="text"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="column2" value="select"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="column3" value="secret"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="column4" value="calendar"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" inputType="text" dataType="text" id="col1"></w2:column>';
    strTarget += '<w2:column width="140" inputType="select" dataType="text" id="col2">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>예</w2:label><w2:value>Y</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>아니오</w2:label><w2:value>N</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    strTarget += '<w2:column width="140" inputType="secret" dataType="text" id="col3"></w2:column>';
    strTarget += '<w2:column width="140" inputType="calendar" dataType="date" viewType="icon" displayMode="label" calendarFormat="yyyyMMdd" displayFormat="yyyy-MM-dd" id="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 상/하/좌/우 방향키 입력 후, 이동된 Cell 위치 + 편집 모드 여부 + (좌/우의 경우) Caret 위치 자동 출력
    // (편집 모드에서는 키 이벤트가 셀 내부 편집 input 으로 가서 gridView onkeyup 프로퍼티 핸들러가 fire 되지 않으므로
    //  document 에 capture-phase keyup 리스너를 1회 등록하여 편집 input 의 방향키 keyup 도 포착)
    if (typeof scwin.moveKeyHandler === 'function') {
        document.removeEventListener('keyup', scwin.moveKeyHandler, true);
    }
    scwin.moveKeyHandler = function (ev) {
        let key = ev && (ev.keyCode || ev.which);
        // 상(38)/하(40)/좌(37)/우(39) 방향키일 때만 이동 결과 출력
        if (key !== 37 && key !== 38 && key !== 39 && key !== 40) {
            return;
        }
        // 현재 target1 그리드의 셀(또는 셀 내부 편집 input)에서 발생한 이벤트인지 확인
        // select(inputType=select) 셀 편집 시 w2selectbox 드롭다운(itemTable)은 grid DOM 밖(body)에
        // 렌더되므로 gridEl.contains() 만으로는 누락됨 → 해당 팝업은 id/class 에 grid id 가 포함되어
        // (예: G_mf_target1___selectbox_col2_itemTable) 이를 기준으로 grid 연관 이벤트로 판정
        let gridEl = document.getElementById(scwin.target1.id);
        if (!gridEl || !ev.target) {
            return;
        }
        let tgt = ev.target;
        let inGrid = gridEl.contains(tgt);
        if (!inGrid) {
            let tid = tgt.id || '';
            let tcls = (typeof tgt.className === 'string') ? tgt.className : '';
            let gid = scwin.target1.id;
            // grid 소유 select 드롭다운 등 grid DOM 밖에 렌더된 grid 연관 요소인지 확인
            if (tid.indexOf(gid) === -1 && tcls.indexOf(gid) === -1) {
                return;
            }
        }
        let dirMap = { 37: '좌(ArrowLeft)', 38: '상(ArrowUp)', 39: '우(ArrowRight)', 40: '하(ArrowDown)' };
        let dir = dirMap[key];
        let row = scwin.target1.getFocusedRowIndex();
        let col = scwin.target1.getFocusedColumnIndex();
        let editing = scwin.target1.isEditing();
        let extra = '';
        // 좌/우의 경우 편집 input 의 Caret(selectionStart) 위치도 출력
        if (key === 37 || key === 39) {
            let el = ev.target;
            let caret = (el && typeof el.selectionStart === 'number') ? el.selectionStart : 'N/A';
            extra = ' Caret=' + caret;
        }
        wf_body_bottom.getObj("scwin").setReturnValue("[방향키 이동] " + dir + " → 이동된 Cell(row=" + row + ", col=" + col + ") 편집모드(isEditing)=" + editing + extra);
    };
    document.addEventListener('keyup', scwin.moveKeyHandler, true);
}
